-- Reviewed against Wikidata direct coordinates; preserve changed records by stopping instead of overwriting.
DO $$
BEGIN
CREATE TEMP TABLE battle_review (id text PRIMARY KEY, old_summary text, new_summary text, lon double precision, lat double precision, clear_point boolean, old_links text[]) ON COMMIT DROP;
Haswa in''the Allahabad District, between the Ganges and the Jumna. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Khajuha was fought on January 5, 1659, between the newly crowned Mughal Emperor Aurangzeb and Shah Shuja who also declared himself Mughal Emperor in Bengal. Shuja''s army rested by the tank of Khajwa, about 30 miles to the west of Fatehpur-
Haswa in''the Allahabad District, between the Ganges and the Jumna. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 80.524, 26.052, false, ARRAY['mughal']::text[]),
('battle-battle-of-kolhapur-1659', 'On 28 December 1659, near Kolhapur, a Maratha force under Shivaji defeated a larger Bijapur army led by Rustam Zaman, who fled the field. It was the Marathas'' second major victory over Bijapur, after Pratapgad. The site lay within the borders of Bijapur Sultanate that year (per Cliopatria).', 'On 28 December 1659, near Kolhapur, a Maratha force under Shivaji defeated a larger Bijapur army led by Rustam Zaman, who fled the field. It was the Marathas'' second major victory over Bijapur, after Pratapgad. The battle location is not recorded here.', 74.2333, 16.7, true, ARRAY['bijapur']::text[]),
('battle-battle-of-marg-o-1659', 'The Battle of Margão was a military conflict between the Portuguese Empire and the Sultanate of Bijapur that took place in 1659. The battle resulted in a decisive victory for the Portuguese. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Margão was a military conflict between the Portuguese Empire and the Sultanate of Bijapur that took place in 1659. The battle resulted in a decisive victory for the Portuguese. The battle location is not recorded here.', 73.9583, 15.2719, true, ARRAY[]::text[]),
('battle-battle-of-chakan-1660', 'The Battle of Chakan in 1660 took place between Mughal forces led by Shaista Khan and Maratha forces commanded by Firangoji Narsala at Chakan in Maharashtra. Shaista Khan''s Mughal forces emerged victorious by besieging the Chakan fort, leading to the surrender of the Maratha commander Firangoji. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Chakan in 1660 took place between Mughal forces led by Shaista Khan and Maratha forces commanded by Firangoji Narsala at Chakan in Maharashtra. Shaista Khan''s Mughal forces emerged victorious by besieging the Chakan fort, leading to the surrender of the Maratha commander Firangoji. The battle location is not recorded here.', 73.8619, 18.7603, true, ARRAY['mughal']::text[]),
('battle-battle-of-pavan-khind-1660', 'The Battle of Pavan Khind was a rearguard last stand that took place in September 1660, at a mountain pass in the vicinity of Vishalgad between the forces of the Maratha and the pursuing Bijapur Sultanate forces. The site lay within the borders of Bijapur Sultanate that year (per Cliopatria).', 'The Battle of Pavan Khind was a rearguard last stand that took place in September 1660, at a mountain pass in the vicinity of Vishalgad between the forces of the Maratha and the pursuing Bijapur Sultanate forces. The recorded point lies within the borders of Bijapur Sultanate that year (per Cliopatria).', 73.8333, 16.8667, false, ARRAY['bijapur']::text[]),
('battle-battle-of-umberkhind-1661', 'On 3 February 1661, in the Umberkhind pass of the Sahyadri hills near Khopoli, Shivaji''s Maratha forces ambushed a Mughal army led by Kartalab Khan. After about two hours the Mughals surrendered their arms and paid a ransom to be allowed to leave. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'On 3 February 1661, in the Umberkhind pass of the Sahyadri hills near Khopoli, Shivaji''s Maratha forces ambushed a Mughal army led by Kartalab Khan. After about two hours the Mughals surrendered their arms and paid a ransom to be allowed to leave. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 73.0833, 18.75, false, ARRAY['mughal']::text[]),
('battle-battle-of-surat-1664', 'The Battle of Surat, also known as the Sack of Surat, was a land battle that took place on 5 January 1664 and ended on 13 January 1664, near the city of Surat, in present-day Gujarat, India, between Shivaji, leader of the fledgling Maratha State and Inayat Khan, a Mughal commander. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Surat, also known as the Sack of Surat, was a land battle that took place on 5 January 1664 and ended on 13 January 1664, near the city of Surat, in present-day Gujarat, India, between Shivaji, leader of the fledgling Maratha State and Inayat Khan, a Mughal commander. The recorded point lies outside the kingdoms mapped in the atlas that year.', 72.8333, 21.1667, false, ARRAY[]::text[]),
('battle-battle-of-purandar-1665', 'The Battle of Purandar was fought between the Mughal Empire and the Marathas in 1665. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Purandar was fought between the Mughal Empire and the Marathas in 1665. The battle location is not recorded here.', 73.9833, 18.2833, true, ARRAY['mughal']::text[]),
('battle-battle-of-sinhagad-1670', 'The Battle of Sinhagad, also known as Battle of Kondhana, involved an attack by Marathas during the night of 4 February 1670 on the Mughal fort of Sinhagad, near the city of Pune, Maharashtra. The Marathas captured the fort. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Sinhagad, also known as Battle of Kondhana, involved an attack by Marathas during the night of 4 February 1670 on the Mughal fort of Sinhagad, near the city of Pune, Maharashtra. The Marathas captured the fort. The battle location is not recorded here.', 73.7553, 18.3657, true, ARRAY['mughal']::text[]),
('battle-battle-of-saraighat-1671', 'The Battle of Saraighat was a naval battle fought in 1671 between the Mughal Empire, and the Ahom Kingdom on the Brahmaputra river at Saraighat, now in Guwahati, Assam, India. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Saraighat was a naval battle fought in 1671 between the Mughal Empire, and the Ahom Kingdom on the Brahmaputra river at Saraighat, now in Guwahati, Assam, India. The battle location is not recorded here.', 91.6722, 26.1754, true, ARRAY['mughal']::text[]),
('battle-attack-in-hooghly-1671', 'The Attack in Hooghly was a Danish attack on two Bengali ships during the Dano-Mughal War in 1671. The Danes succeeded in blowing up the Bengali ships, and violence continued off the coasts of Kalingapatnam and Balasore. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Attack in Hooghly was a Danish attack on two Bengali ships during the Dano-Mughal War in 1671. The Danes succeeded in blowing up the Bengali ships, and violence continued off the coasts of Kalingapatnam and Balasore. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 88.39, 22.9, false, ARRAY['mughal']::text[]),
('battle-battle-of-salher-1672', 'In February 1672, near the fort of Salher in Nashik district, Maratha forces under Prataprao Gujar and Moropant Pingle defeated a larger Mughal force. It is described as the first battle in which the Mughals lost in the open field. The site lay outside every kingdom mapped in the atlas that year.', 'In February 1672, near the fort of Salher in Nashik district, Maratha forces under Prataprao Gujar and Moropant Pingle defeated a larger Mughal force. It is described as the first battle in which the Mughals lost in the open field. The recorded point lies outside the kingdoms mapped in the atlas that year.', 72.8333, 21.1667, false, ARRAY[]::text[]),
('battle-battle-of-kohat-1674', 'The Battle of Kohat was a military engagement fought in 1674 between the forces of the Bangash tribe and the Afridi tribe of the Pashtun. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Kohat was a military engagement fought in 1674 between the forces of the Bangash tribe and the Afridi tribe of the Pashtun. The battle location is not recorded here.', 71.4397, 33.59, true, ARRAY['mughal']::text[]),
('battle-battle-of-gumbat-1675', 'The Battle of Gumbat was a military engagement fought in Gumbat between the forces of Khushal Khan Khattak and the Bangash tribe under Sher Muhammad Bangash Kohati. The battle resulted in a defeat for the Khattak forces with Khushal Khan himself being wounded during the engagement. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Gumbat was a military engagement fought in Gumbat between the forces of Khushal Khan Khattak and the Bangash tribe under Sher Muhammad Bangash Kohati. The battle resulted in a defeat for the Khattak forces with Khushal Khan himself being wounded during the engagement. The battle location is not recorded here.', 72.4737, 34.2595, true, ARRAY['mughal']::text[]),
('battle-battle-of-sangamner-1679', 'The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The battle location is not recorded here.', 74.22, 19.57, true, ARRAY['mughal']::text[]),
('battle-battle-of-dodah-1680', 'The Battle of Dodah was a military engagement fought in 1680 in the Bangash territory of the northwestern frontier, in the present-day Khyber Pakhtunkhwa region of Pakistan. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Dodah was a military engagement fought in 1680 in the Bangash territory of the northwestern frontier, in the present-day Khyber Pakhtunkhwa region of Pakistan. The battle location is not recorded here.', 72.18, 34.343, true, ARRAY['mughal']::text[]),
('battle-battle-of-itakhuli-1682', 'The Battle of Itakhuli was fought in August 1682 between the Ahom Kingdom and the Mughal Empire in an area that is in modern-day Assam. The Ahoms pushed back Mughal control to the west of the Manas River. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Itakhuli was fought in August 1682 between the Ahom Kingdom and the Mughal Empire in an area that is in modern-day Assam. The Ahoms pushed back Mughal control to the west of the Manas River. The battle location is not recorded here.', 91.7502, 26.1806, true, ARRAY[]::text[]),
('battle-battle-of-kalyan-1682', 'The Battle of Kalyan was a series of engagements between the Mughal Empire and the Maratha Kingdom over Kalyan in 1682–83, during the Deccan wars. Mughal forces under Bahadur Khan captured Kalyan on 28 November 1682 after defeating a Maratha force. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Kalyan was a series of engagements between the Mughal Empire and the Maratha Kingdom over Kalyan in 1682–83, during the Deccan wars. Mughal forces under Bahadur Khan captured Kalyan on 28 November 1682 after defeating a Maratha force. The battle location is not recorded here.', 73.15, 19.25, true, ARRAY['mughal']::text[]),
('battle-battle-of-bhangani-1688', 'The Battle of Bhangani was fought between Guru Gobind Singh''s army and Bhim Chand of Bilaspur on 18 September 1686 or 1688, at Bhangani near Paonta Sahib. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Bhangani was fought between Guru Gobind Singh''s army and Bhim Chand of Bilaspur on 18 September 1686 or 1688, at Bhangani near Paonta Sahib. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 77.7284, 30.4891, false, ARRAY['mughal']::text[]),
('battle-battle-of-nadaun-1691', 'The Battle of Nadaun, alternatively known as the Hussaini Yudh, was fought at Nadaun, between Raja Bhim Chand of Bilaspur and the Mughals under Alif Khan. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Nadaun, alternatively known as the Hussaini Yudh, was fought at Nadaun, between Raja Bhim Chand of Bilaspur and the Mughals under Alif Khan. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 76.35, 31.7833, false, ARRAY['mughal']::text[]),
('battle-battle-of-daman-1694', 'The Battle of Daman took place on 23 March 1694, when a Portuguese squadron, commanded by General António Machado de Brito, pursued and attacked an Omani squadron sailing off Daman. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Daman took place on 23 March 1694, when a Portuguese squadron, commanded by General António Machado de Brito, pursued and attacked an Omani squadron sailing off Daman. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 72.85, 20.42, false, ARRAY['mughal']::text[]),
('battle-battle-of-guler-1696', 'The Battle of Guler was fought between Mughal forces led by Hussain Khan, and the Raja of Guler, aided by the Akal Sena. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Guler was fought between Mughal forces led by Hussain Khan, and the Raja of Guler, aided by the Akal Sena. The battle location is not recorded here.', 76.16, 32, true, ARRAY['mughal']::text[]),
('battle-battle-of-anandpur-1700', 'The Battle of Anandpur was fought at Anandpur, between the armies of the Sikh Guru Gobind Singh and the Mughal forces aided by the Nawab of Bahawalpur state, Rajas of the Sivalik Hills. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Anandpur was fought at Anandpur, between the armies of the Sikh Guru Gobind Singh and the Mughal forces aided by the Nawab of Bahawalpur state, Rajas of the Sivalik Hills. The battle location is not recorded here.', 76.5, 31.23, true, ARRAY['mughal']::text[]),
('battle-battle-of-satara-1700', 'The Battle of Satara was fought between the Mughal Empire and Maratha Kingdom between December 1699 and 21 April 1700. The battle started when the Mughal Emperor Aurangzeb personally marched towards Satara, accompanied by 10,000 Mughal soldiers. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Satara was fought between the Mughal Empire and Maratha Kingdom between December 1699 and 21 April 1700. The battle started when the Mughal Emperor Aurangzeb personally marched towards Satara, accompanied by 10,000 Mughal soldiers. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 73.98, 17.68, false, ARRAY['mughal']::text[]),
('battle-battle-of-taragarh-1700', 'The Battle of Taragarh was fought between the Sikh forces led by Sahibzada Ajit Singh and the Rajas of the Sivalik Hills. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Taragarh was fought between the Sikh forces led by Sahibzada Ajit Singh and the Rajas of the Sivalik Hills. The battle location is not recorded here.', 76.5, 31.23, true, ARRAY['mughal']::text[]);
  IF EXISTS (SELECT 1 FROM battle_review r JOIN events e ON e.id=r.id WHERE e.category IS DISTINCT FROM 'battle' OR e.summary IS DISTINCT FROM r.old_summary OR e.map_point IS NULL OR abs(ST_X(e.map_point)-r.lon)>0.00000001 OR abs(ST_Y(e.map_point)-r.lat)>0.00000001) THEN
    RAISE EXCEPTION 'A battle changed since review; stop and review it before updating';
  END IF;
  IF EXISTS (SELECT 1 FROM battle_review r JOIN events e ON e.id=r.id WHERE r.old_links IS DISTINCT FROM COALESCE((SELECT array_agg(k.kingdom_id ORDER BY k.kingdom_id) FROM event_kingdoms k WHERE k.event_id=r.id AND k.connection='inside_borders'), ARRAY[]::text[])) THEN
    RAISE EXCEPTION 'A battle link changed since review; stop and review it before updating';
  END IF;
  IF EXISTS (SELECT 1 FROM battle_review r JOIN event_kingdom_sources s ON s.event_id=r.id AND s.connection='inside_borders' WHERE r.clear_point) THEN
    RAISE EXCEPTION 'A battle link has source records; review them before removing it';
  END IF;
  IF EXISTS (SELECT 1 FROM battle_review r JOIN events e ON e.id=r.id WHERE NOT EXISTS (SELECT 1 FROM information_sources s WHERE s.event_id=r.id AND s.source_id='wikidata' AND s.note='Date and place.') OR NOT EXISTS (SELECT 1 FROM information_sources s WHERE s.event_id=r.id AND s.source_id='cliopatria' AND s.note='Which kingdom''s borders contained the site.')) THEN
    RAISE EXCEPTION 'A battle source changed since review; stop and review it before updating';
  END IF;
DELETE FROM event_kingdoms k USING battle_review r WHERE r.id=k.event_id AND r.clear_point AND k.connection='inside_borders';
DELETE FROM information_sources s USING battle_review r WHERE r.id=s.event_id AND r.clear_point AND s.source_id='cliopatria' AND s.note='Which kingdom''s borders contained the site.';
UPDATE information_sources s SET note=CASE WHEN r.clear_point THEN 'Date.' ELSE 'Date and recorded location.' END FROM battle_review r WHERE r.id=s.event_id AND s.source_id='wikidata' AND s.note='Date and place.';
UPDATE information_sources s SET note='Which kingdom''s borders contain the recorded point.' FROM battle_review r WHERE r.id=s.event_id AND NOT r.clear_point AND s.source_id='cliopatria' AND s.note='Which kingdom''s borders contained the site.';
UPDATE events e SET summary=r.new_summary, map_point=CASE WHEN r.clear_point THEN NULL ELSE e.map_point END FROM battle_review r WHERE r.id=e.id;
END $$;
