INSERT INTO battle_review VALUES
('battle-battle-of-vatapi-642', 'The Battle of Vatapi was a decisive engagement which took place between the Pallavas and Chalukyas near the Chalukya capital of Vatapi in 642. The battle resulted in the defeat of the Chalukya king Pulakeshin II in 642 CE and the commencement of Pallava occupation of Vatapi lasted until 654. The site lay within the borders of Chalukya (Badami) that year (per Cliopatria).', 'The Battle of Vatapi was a decisive engagement which took place between the Pallavas and Chalukyas near the Chalukya capital of Vatapi in 642. The battle resulted in the defeat of the Chalukya king Pulakeshin II in 642 CE and the commencement of Pallava occupation of Vatapi lasted until 654. The battle location is not recorded here.', 75.6803, 15.9203, true, ARRAY['chalukya-badami']::text[]),
('battle-battle-of-rasil-644', 'The Battle of Rasil was fought between the Rashidun Caliphate and the Rai dynasty of Sindh in early 640 AD in present-day Pakistan. It was the first battle the Muslims fought in the Indian subcontinent. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Rasil was fought in 644 CE in present-day Pakistan. The battle location is not recorded here.', 81.7684, 31.2421, true, ARRAY[]::text[]),
('battle-battle-of-chabuheluo-647', 'The Battle of Chabuheluo was a battle that took place between an alliance led by the Tang dynasty and the Kingdom of Kannauj in 648 AD. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Chabuheluo was a battle that took place between an alliance led by the Tang dynasty and the Kingdom of Kannauj in 648 AD. The battle location is not recorded here.', 85.1414, 25.61, true, ARRAY[]::text[]),
('battle-battle-of-badghis-654', 'Battle of Badghis, 654. Wikidata records its date and place; there is no article that describes this battle on its own. The site lay outside every kingdom mapped in the atlas that year.', 'Battle of Badghis, 654. Wikidata records its date; there is no article that describes this battle on its own. The battle location is not recorded here.', 63.75, 35, true, ARRAY[]::text[]),
('battle-battle-of-aror-712', 'The Battle of Aror took place in 712 AD between the Umayyad forces under Muhammad ibn al-Qasim and the army of the Brahmin dynasty of Sindh under Raja Dahir. At the Battle of Aror, Muhammad ibn al-Qasim was met by Dahir''s forces in battle. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Aror took place in 712 AD between the Umayyad forces under Muhammad ibn al-Qasim and the army of the Brahmin dynasty of Sindh under Raja Dahir. At the Battle of Aror, Muhammad ibn al-Qasim was met by Dahir''s forces in battle. The recorded point lies outside the kingdoms mapped in the atlas that year.', 68.9833, 27.65, false, ARRAY[]::text[]),
('battle-battle-of-qandabil-720', 'In 720, the sons of al-Muhallab, who had rebelled against the Umayyads, fled to Qandabil in Sind hoping for refuge. Their ally shut the gates against them, and they were killed fighting their Umayyad pursuer, Hilal ibn Ahwaz al-Tamimi. The site lay outside every kingdom mapped in the atlas that year.', 'In 720, the sons of al-Muhallab, who had rebelled against the Umayyads, fled to Qandabil in Sind hoping for refuge. Their ally shut the gates against them, and they were killed fighting their Umayyad pursuer, Hilal ibn Ahwaz al-Tamimi. The battle location is not recorded here.', 67.4833, 28.6167, true, ARRAY[]::text[]),
('battle-battle-of-kharistan-737', 'The Battle of Kharistan was fought between the forces of the Umayyad Caliphate and the Turkic Türgesh in December 737 near the town of Kharistan in Juzjan, eastern Khurasan. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Kharistan was fought between the forces of the Umayyad Caliphate and the Turkic Türgesh in December 737 near the town of Kharistan in Juzjan, eastern Khurasan. The battle location is not recorded here.', 64.75, 35.9333, true, ARRAY[]::text[]),
('battle-friday-battle-748', 'The site lay outside every kingdom mapped in the atlas that year.', 'The battle location is not recorded here.', 62, 36, true, ARRAY[]::text[]),
('battle-battle-of-kanchi-803', 'The site lay within the borders of Pallava that year (per Cliopatria).', 'The battle location is not recorded here.', 79.7078, 12.8308, true, ARRAY['pallava']::text[]),
('battle-battle-of-balkh-900', 'The Battle of Balkh took place between the armies of the Samanid Empire under the command of Emir Isma''il ibn Ahmad and Saffarid forces under Emir Amr ibn al-Layth in 900. The Saffarid army was defeated by the Samanid forces, and Amr ibn al-Layth was captured. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Balkh took place between the armies of the Samanid Empire under the command of Emir Isma''il ibn Ahmad and Saffarid forces under Emir Amr ibn al-Layth in 900. The Saffarid army was defeated by the Samanid forces, and Amr ibn al-Layth was captured. The battle location is not recorded here.', 66.8989, 36.7581, true, ARRAY[]::text[]),
('battle-battle-of-takkolam-949', 'The Battle of Takkolam was a military engagement between a contingent of troops led by Rajaditya, crown prince and eldest son of the Chola king Parantaka I, and another led by the Rashtrakuta king Krishna III at Takkolam in southern India. The site lay within the borders of Chola that year (per Cliopatria).', 'The Battle of Takkolam was a military engagement between a contingent of troops led by Rajaditya, crown prince and eldest son of the Chola king Parantaka I, and another led by the Rashtrakuta king Krishna III at Takkolam in southern India. The battle location is not recorded here.', 79.7353, 13.0159, true, ARRAY['chola']::text[]),
('battle-battle-of-ghazni-998', 'The Battle of Ghazni was fought in March 998 AD between the rival Ghaznavid forces of Amir Ismail and those of his elder brother Mahmud of Ghazni. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'The Battle of Ghazni was fought in March 998 AD between the rival Ghaznavid forces of Amir Ismail and those of his elder brother Mahmud of Ghazni. The battle location is not recorded here.', 68.4233, 33.5492, true, ARRAY['ghaznavid']::text[]),
('battle-battle-of-peshawar-1001', 'The Battle of Peshawar was fought on 27 November 1001 between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Jayapala, near Peshawar. Jayapala was defeated and captured, and as a result of the humiliation of the defeat, he later immolated himself in a funeral pyre. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'The Battle of Peshawar was fought on 27 November 1001 between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Jayapala, near Peshawar. Jayapala was defeated and captured, and as a result of the humiliation of the defeat, he later immolated himself in a funeral pyre. The recorded point lies within the borders of Ghaznavid that year (per Cliopatria).', 71.5675, 34.0144, false, ARRAY['ghaznavid']::text[]),
('battle-battle-of-chach-1009', 'The Battle of Chach or Battle of Chaach was fought in 1009 AD between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Anandapala, near Hazro, resulting in the latter''s defeat. This left the north Indian region vulnerable to further invasions. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Chach or Battle of Chaach was fought in 1009 AD between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Anandapala, near Hazro, resulting in the latter''s defeat. This left the north Indian region vulnerable to further invasions. The battle location is not recorded here.', 72.4928, 33.9097, true, ARRAY[]::text[]),
('battle-battle-of-nandana-1014', 'The Battle of Nandana or Battle of Nazin was a decisive engagement in March 1014 CE during Mahmud of Ghazni''s campaign against the Hindu Shahis in the Salt Range region of present-day Pakistan. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Nandana or Battle of Nazin was a decisive engagement in March 1014 CE during Mahmud of Ghazni''s campaign against the Hindu Shahis in the Salt Range region of present-day Pakistan. The recorded point lies outside the kingdoms mapped in the atlas that year.', 73.2359, 32.728, false, ARRAY[]::text[]),
('battle-battle-of-the-river-tausi-1014', 'The Battle of River Tausi in 1014 CE was a decisive Ghaznavid victory during Mahmud of Ghazni''s campaign against the Hindu Shahis. Trilochanapala, with Kashmiri Lohara contingents under commander Tunga, held the left bank of the Tausi, modern Poonch River. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of River Tausi in 1014 CE was a decisive Ghaznavid victory during Mahmud of Ghazni''s campaign against the Hindu Shahis. Trilochanapala, with Kashmiri Lohara contingents under commander Tunga, held the left bank of the Tausi, modern Poonch River. The battle location is not recorded here.', 73.7485, 33.3323, true, ARRAY[]::text[]),
('battle-battle-of-the-ramganga-1020', 'The Battle of the Ramganga or Battle of the Rahib in December 1020 AD was a decisive battle, during Mahmud of Ghazni''s second invasion of the Doab. Ghaznavid forces defeated the Hindu Shahi army of Trilocanapala at the upper course Ramganga River known as River Ruhut near Afzalgarh. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of the Ramganga or Battle of the Rahib in December 1020 AD was a decisive battle, during Mahmud of Ghazni''s second invasion of the Doab. Ghaznavid forces defeated the Hindu Shahi army of Trilocanapala at the upper course Ramganga River known as River Ruhut near Afzalgarh. The battle location is not recorded here.', 79.2573, 30.0966, true, ARRAY[]::text[]),
('battle-battle-of-somnath-1026', 'The sack of Somnath, on 6–8 January 1026, was a campaign led by Mahmud of Ghazni against the Chaulukya dynasty of Gujarat, his fifteenth invasion of India. It ended with the destruction of the Somnath Temple. The site lay outside every kingdom mapped in the atlas that year.', 'The sack of Somnath, on 6–8 January 1026, was a campaign led by Mahmud of Ghazni against the Chaulukya dynasty of Gujarat, his fifteenth invasion of India. It ended with the destruction of the Somnath Temple. The battle location is not recorded here.', 70.37, 20.91, true, ARRAY[]::text[]),
('battle-battle-of-sarakhs-1038', 'The Battle of Sarakhs took place in 1038 between the Seljuk army under the command of Chaghri Beg, Tughril I, and Ibrahim Inal and the Ghaznavid army under the command of Begtoghdi and Subashi. As a result of the battle, the Ghaznavids were defeated. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Sarakhs took place in 1038 between the Seljuk army under the command of Chaghri Beg, Tughril I, and Ibrahim Inal and the Ghaznavid army under the command of Begtoghdi and Subashi. As a result of the battle, the Ghaznavids were defeated. The battle location is not recorded here.', 61.1578, 36.545, true, ARRAY[]::text[]),
('battle-battle-of-koppam-1054', 'The Battle of Koppam was fought between the Medieval Chola kings Rajadhiraja Chola I and Rajendra Chola II with the Chalukya king Someshvara I in 1054, or in 1052 according to Sen. The site lay within the borders of Chera and Chola that year (per Cliopatria).', 'The Battle of Koppam was fought between the Medieval Chola kings Rajadhiraja Chola I and Rajendra Chola II with the Chalukya king Someshvara I in 1054, or in 1052 according to Sen. The battle location is not recorded here.', 76.1833, 10.8833, true, ARRAY['chera','chola']::text[]),
('battle-battle-of-kudal-sangamam-1062', 'The First Battle of Kudal-Sangamam was fought in 1062 by the forces of the Chola king Rajendra Chola II and the Western Chalukya king Someshvara I at Kudal-Sangamam, where the Krishna and the Tungabhadra meet. The site lay within the borders of Chalukya (Kalyani) that year (per Cliopatria).', 'The First Battle of Kudal-Sangamam was fought in 1062 by the forces of the Chola king Rajendra Chola II and the Western Chalukya king Someshvara I at Kudal-Sangamam, where the Krishna and the Tungabhadra meet. The battle location is not recorded here.', 76.06, 16.2036, true, ARRAY['chalukya-kalyani']::text[]),
('battle-battle-of-vijayawada-1068', 'The Battle of Vijayawada was fought in 1068 between the Chola army under Virarajendra Chola and the Western Chalukya army commanded by Vikramaditya VI near the present-day city of Vijayawada in Andhra Pradesh, India. The site lay within the borders of Chola that year (per Cliopatria).', 'The Battle of Vijayawada was fought in 1068 between the Chola army under Virarajendra Chola and the Western Chalukya army commanded by Vikramaditya VI near the present-day city of Vijayawada in Andhra Pradesh, India. The battle location is not recorded here.', 80.6167, 16.5167, true, ARRAY['chola']::text[]),
('battle-battle-of-ghazni-1117', 'The Battle of Ghazni was fought in 1117 between the Seljuk forces supporting the claim of Bahram of Ghazna and the army of his brother the ruling Sultan Arslan-Shah of Ghazna. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'The Battle of Ghazni was fought in 1117 between the Seljuk forces supporting the claim of Bahram of Ghazna and the army of his brother the ruling Sultan Arslan-Shah of Ghazna. The battle location is not recorded here.', 68.4233, 33.5492, true, ARRAY['ghaznavid']::text[]),
('battle-battle-of-kachhi-1142', 'Battle of Kachhi also known as Battle of Jandari was fought between the Khanate of Kalat and Kalhora Dyansty led by Mian Noor Mohammad Kalhoro due to the territorial dispute over the Kachhi region in present-day Balochistan. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'Battle of Kachhi also known as Battle of Jandari was fought between the Khanate of Kalat and Kalhora Dyansty led by Mian Noor Mohammad Kalhoro due to the territorial dispute over the Kachhi region in present-day Balochistan. The recorded point lies within the borders of Ghaznavid that year (per Cliopatria).', 67.3497, 29.106, false, ARRAY['ghaznavid']::text[]),
('battle-battle-of-ghazni-1148', 'The Battle of Ghazni was fought in 1148 between the Ghurid army of Sayf al-Din Suri and the army of the Ghaznavid Sultan Bahram-Shah of Ghazna. The Ghurid ruler defeated Bahram-Shah and took the city while Bahram-Shah fled to Kurram District in present day Pakistan. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'The Battle of Ghazni was fought in 1148 between the Ghurid army of Sayf al-Din Suri and the army of the Ghaznavid Sultan Bahram-Shah of Ghazna. The Ghurid ruler defeated Bahram-Shah and took the city while Bahram-Shah fled to Kurram District in present day Pakistan. The battle location is not recorded here.', 68.4233, 33.5492, true, ARRAY['ghaznavid']::text[]),
('battle-battle-of-ghazni-1151', 'The Battle of Ghazni was fought in 1151 between the Ghurid army of Ala al-Din Husayn and the army of the Ghaznavid Sultan Bahram-Shah of Ghazna. The Ghurid ruler defeated Bahram-Shah, captured the city, and destroyed it as revenge for the execution of his brother Quṭb ud-Dīn in 1149. The site lay within the borders of Ghaznavid that year (per Cliopatria).', 'The Battle of Ghazni was fought in 1151 between the Ghurid army of Ala al-Din Husayn and the army of the Ghaznavid Sultan Bahram-Shah of Ghazna. The Ghurid ruler defeated Bahram-Shah, captured the city, and destroyed it as revenge for the execution of his brother Quṭb ud-Dīn in 1149. The battle location is not recorded here.', 68.4233, 33.5492, true, ARRAY['ghaznavid']::text[]),
('battle-battle-of-nettur-1188', 'The Battle of Nettur was an engagement between the Chola Emperor Kulothunga Chola III and Vira Pandya, the claimant to the Pandya throne in 1188. The subsequent crisis was erupted in the aftermath of the Pandyan Civil War, which led to the ascension of Vira Pandya. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Nettur was an engagement between the Chola Emperor Kulothunga Chola III and Vira Pandya, the claimant to the Pandya throne in 1188. The subsequent crisis was erupted in the aftermath of the Pandyan Civil War, which led to the ascension of Vira Pandya. The battle location is not recorded here.', 75.3811, 31.38, true, ARRAY[]::text[]),
('battle-battle-of-bagar-1192', 'The Rebellion of Jatwan was a revolt staged by Jatwan against the Ghurid empire in 1192 CE. The Ghurids defeated the rebel forces and Jatwan was killed in the battle. The site lay within the borders of Chauhan that year (per Cliopatria).', 'The Rebellion of Jatwan was a revolt staged by Jatwan against the Ghurid empire in 1192 CE. The Ghurids defeated the rebel forces and Jatwan was killed in the battle. The recorded point lies within the borders of Chauhan that year (per Cliopatria).', 75.5, 28.18, false, ARRAY['chauhan']::text[]),
('battle-second-battle-of-tarain-1192', 'The Second Battle of Tarain or Second Battle of Tararoi was fought in 1192 between the Ghurid forces of Muhammad Ghuri and the Rajput Confederacy of Prithviraj Chauhan. It took place near Tarain, which is 110 kilometres, north of Delhi. The site lay within the borders of Ghurid that year (per Cliopatria).', 'The Second Battle of Tarain or Second Battle of Tararoi was fought in 1192 between the Ghurid forces of Muhammad Ghuri and the Rajput Confederacy of Prithviraj Chauhan. It took place near Tarain, which is 110 kilometres, north of Delhi. The recorded point lies within the borders of Ghurid that year (per Cliopatria).', 76.94, 29.78, false, ARRAY['ghurid']::text[]),
('battle-battle-of-chandawar-1194', 'The Battle of Chandawar was fought in 1194 between Muhammad of Ghor and Jayachandra of the Gahadavala dynasty. It took place at Chandawar, on the Yamuna River close to Agra. The victory of this battle gave Muhammad control of much of North India. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Chandawar was fought in 1194 between Muhammad of Ghor and Jayachandra of the Gahadavala dynasty. It took place at Chandawar, on the Yamuna River close to Agra. The victory of this battle gave Muhammad control of much of North India. The recorded point lies outside the kingdoms mapped in the atlas that year.', 78.367, 27.107, false, ARRAY[]::text[]),
('battle-battle-of-andkhud-1204', 'The battle of Andkhud, also spelt as battle of Andkhui, was fought in 1204 on the bank of river Oxus near Andkhoy in present-day Afghanistan. It was fought between the Ghurid forces of Muhammad of Ghor against the Qara Khitai forces led by Tayangu of Taraz. The site lay outside every kingdom mapped in the atlas that year.', 'The battle of Andkhud, also spelt as battle of Andkhui, was fought in 1204 on the bank of river Oxus near Andkhoy in present-day Afghanistan. It was fought between the Ghurid forces of Muhammad of Ghor against the Qara Khitai forces led by Tayangu of Taraz. The recorded point lies outside the kingdoms mapped in the atlas that year.', 65.1253, 36.953, false, ARRAY[]::text[]),
('battle-battle-of-waliyan-1221', 'The Battle of Parwan was fought between Sultan Jalal al-Din Mangburni of the Khwarazmian Empire and the Mongols ruled by Genghis Khan in September 1221 AD during the Mongol invasion of the Khwarazmian Empire at Parwan, north of Kabul, in present-day Afghanistan. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Parwan was fought between Sultan Jalal al-Din Mangburni of the Khwarazmian Empire and the Mongols ruled by Genghis Khan in September 1221 AD during the Mongol invasion of the Khwarazmian Empire at Parwan, north of Kabul, in present-day Afghanistan. The recorded point lies outside the kingdoms mapped in the atlas that year.', 68.8786, 35.4783, false, ARRAY[]::text[]),
('battle-battle-of-parwan-1221', 'The Battle of Parwan was fought between Sultan Jalal al-Din Mangburni of the Khwarazmian Empire and the Mongols ruled by Genghis Khan in September 1221 AD during the Mongol invasion of the Khwarazmian Empire at Parwan, north of Kabul, in present-day Afghanistan. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Parwan was fought between Sultan Jalal al-Din Mangburni of the Khwarazmian Empire and the Mongols ruled by Genghis Khan in September 1221 AD during the Mongol invasion of the Khwarazmian Empire at Parwan, north of Kabul, in present-day Afghanistan. The battle location is not recorded here.', 69, 35, true, ARRAY[]::text[]),
('battle-battle-of-indus-1221', 'The Battle of the Indus was fought on the banks of the Indus River, on 24 November 1221, between the armies commanded by Jalal al-Din of the Khwarazmian Empire, and Genghis Khan of the Mongol Empire. The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'The Battle of the Indus was fought on the banks of the Indus River, on 24 November 1221, between the armies commanded by Jalal al-Din of the Khwarazmian Empire, and Genghis Khan of the Mongol Empire. The recorded point lies within the borders of Delhi Sultanate that year (per Cliopatria).', 72.18, 33.77, false, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-ucha-1222', 'The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'The battle location is not recorded here.', 74, 31, true, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-herat-1270', 'The Battle of Herat was fought between the Ilkhanid forces of Abaqa Khan and the invading Chagatai forces of Ghiyas-ud-din Baraq on 22 July 1270. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Herat was fought between the Ilkhanid forces of Abaqa Khan and the invading Chagatai forces of Ghiyas-ud-din Baraq on 22 July 1270. The battle location is not recorded here.', 61.47, 34.34, true, ARRAY[]::text[]),
('battle-battle-of-beas-river-1285', 'The Battle of Beas River took place between the Chagatai Khanate and the Mamluk Sultanate of Delhi on 9 March 1285. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Beas River took place between the Chagatai Khanate and the Mamluk Sultanate of Delhi on 9 March 1285. The battle location is not recorded here.', 77.0909, 32.3534, true, ARRAY[]::text[]),
('battle-battle-of-jhain-1291', 'The Capture of Jhain was a military expedition carried out by the Delhi Sultanate under Jalal-ud-din Khalji against the Kingdom of Ranthambore. It took place in the March of 1291 when the Delhi forces defeated the Ranthambore forces under Gurdan Saini and captured the city of Jhain. The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'The Capture of Jhain was a military expedition carried out by the Delhi Sultanate under Jalal-ud-din Khalji against the Kingdom of Ranthambore. It took place in the March of 1291 when the Delhi forces defeated the Ranthambore forces under Gurdan Saini and captured the city of Jhain. The recorded point lies within the borders of Delhi Sultanate that year (per Cliopatria).', 76.4823, 25.8908, false, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-sind-1298', 'In 1298–99, a Mongol army invaded the Sindh region of the Delhi Sultanate, and occupied the fort of Sivistan in present-day Pakistan. The Delhi Sultan Alauddin Khalji dispatched his general Zafar Khan to evict the Mongols. Zafar Khan recaptured the fort, and imprisoned the Mongol leader Saldi and his companions. The site lay outside every kingdom mapped in the atlas that year.', 'In 1298–99, a Mongol army invaded the Sindh region of the Delhi Sultanate, and occupied the fort of Sivistan in present-day Pakistan. The Delhi Sultan Alauddin Khalji dispatched his general Zafar Khan to evict the Mongols. Zafar Khan recaptured the fort, and imprisoned the Mongol leader Saldi and his companions. The recorded point lies outside the kingdoms mapped in the atlas that year.', 67.8629, 26.4234, false, ARRAY[]::text[]),
('battle-battle-of-kili-1299', 'The Battle of Kili was fought in 1299 between the Mongols of the Chagatai Khanate and the Delhi Sultanate. The Mongols, led by Qutlugh Khwaja, invaded India, intending to conquer Delhi and the Indian subcontinent. When they encamped at Kili near Delhi, the Delhi Sultan Alauddin Khalji led an army to check their advance. The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'The Battle of Kili was fought in 1299 between the Mongols of the Chagatai Khanate and the Delhi Sultanate. The Mongols, led by Qutlugh Khwaja, invaded India, intending to conquer Delhi and the Indian subcontinent. When they encamped at Kili near Delhi, the Delhi Sultan Alauddin Khalji led an army to check their advance. The recorded point lies within the borders of Delhi Sultanate that year (per Cliopatria).', 77.2309, 28.6546, false, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-amroha-1305', 'The Battle of Amroha was fought on 20 December 1305 between the armies of the Delhi Sultanate of India and the Mongol Chagatai Khanate of Central Asia. The Delhi force led by Malik Nayak defeated the Mongol army led by Ali Beg and Tartaq near Amroha in present-day Uttar Pradesh. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Amroha was fought on 20 December 1305 between the armies of the Delhi Sultanate of India and the Mongol Chagatai Khanate of Central Asia. The Delhi force led by Malik Nayak defeated the Mongol army led by Ali Beg and Tartaq near Amroha in present-day Uttar Pradesh. The recorded point lies outside the kingdoms mapped in the atlas that year.', 78.4673, 28.9044, false, ARRAY[]::text[]),
('battle-battle-of-ravi-1306', 'In 1306, the Chagatai Khanate ruler Duwa sent an expedition to India, to avenge the Mongol defeat in 1305. The invading army included three contingents led by Kopek, Iqbalmand, and Tai-Bu. The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'In 1306, the Chagatai Khanate ruler Duwa sent an expedition to India, to avenge the Mongol defeat in 1305. The invading army included three contingents led by Kopek, Iqbalmand, and Tai-Bu. The battle location is not recorded here.', 71.8278, 30.6211, true, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-mandavgad-1437', 'The site lay outside every kingdom mapped in the atlas that year.', 'The battle location is not recorded here.', 75.4158, 22.3353, true, ARRAY[]::text[]),
('battle-battle-of-tarnab-1448', 'In spring 1448, east of Herat, the Timurid ruler Ulugh Beg of Samarkand decisively defeated Ala al-Dawla Mirza of Khurasan, during the Second Timurid Succession Crisis. The site lay outside every kingdom mapped in the atlas that year.', 'In spring 1448, east of Herat, the Timurid ruler Ulugh Beg of Samarkand decisively defeated Ala al-Dawla Mirza of Khurasan, during the Second Timurid Succession Crisis. The battle location is not recorded here.', 62.2031, 34.3419, true, ARRAY[]::text[]),
('battle-battle-of-devarakonda-1458', 'The Battle of Devarkonda took place between Gajapati Empire and Bahmani Sultanate in 1458 A.D. at Devarkonda, Telangana, India. In this battle Odia forces led by prince Hamvira Deva under king Gajapati Kapilendra Deva crushed a massive army of Bahmani Muslim forces led by Humayun Shah. The site lay within the borders of Vijayanagara that year (per Cliopatria).', 'The Battle of Devarkonda took place between Gajapati Empire and Bahmani Sultanate in 1458 A.D. at Devarkonda, Telangana, India. In this battle Odia forces led by prince Hamvira Deva under king Gajapati Kapilendra Deva crushed a massive army of Bahmani Muslim forces led by Humayun Shah. The recorded point lies within the borders of Vijayanagara that year (per Cliopatria).', 78.933, 16.7, false, ARRAY['vijayanagara']::text[]),
('battle-battle-of-sarakhs-1459', 'Battle of Sarakhs took place in March 1459, at a location between Merv and Sarakhs. The site lay outside every kingdom mapped in the atlas that year.', 'Battle of Sarakhs took place in March 1459, at a location between Merv and Sarakhs. The battle location is not recorded here.', 61.1578, 36.545, true, ARRAY[]::text[]),
('battle-battle-of-ghwarah-marghah-1460', 'The Battle of Ghwarah Marghah was fought between the Yusufzai Afghan tribal confederacy under Malak Sulaiman Shah Yusufzai and the combined forces of Mirza Ulugh Beg and his allies from the Gigyani tribe near Kabul, Afghanistan. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Ghwarah Marghah was fought between the Yusufzai Afghan tribal confederacy under Malak Sulaiman Shah Yusufzai and the combined forces of Mirza Ulugh Beg and his allies from the Gigyani tribe near Kabul, Afghanistan. The battle location is not recorded here.', 69.1658, 34.5328, true, ARRAY[]::text[]),
('battle-battle-of-calicut-1503', 'The naval Battle of Calicut was a military encounter between the 16 ships of the 4th Portuguese Armada and a fleet led by two Arabic corsairs formed under the orders of the Zamorin of Kozhikode. The site lay outside every kingdom mapped in the atlas that year.', 'The naval Battle of Calicut was a military encounter between the 16 ships of the 4th Portuguese Armada and a fleet led by two Arabic corsairs formed under the orders of the Zamorin of Kozhikode. The battle location is not recorded here.', 75.7803, 11.2478, true, ARRAY[]::text[]),
('battle-battle-of-pandarane-1504', 'The Battle of Pandarane was a naval engagement between the Portuguese forces commanded by Lopo Soares de Albergaria, a famous Portuguese commander, and a large fleet of then Mamluk Sultan. The Portuguese were victorious. The site lay within the borders of Vijayanagara that year (per Cliopatria).', 'The Battle of Pandarane was a naval engagement between the Portuguese forces commanded by Lopo Soares de Albergaria, a famous Portuguese commander, and a large fleet of then Mamluk Sultan. The Portuguese were victorious. The battle location is not recorded here.', 75.7, 11.43, true, ARRAY['vijayanagara']::text[]),
('battle-battle-of-qalat-i-ghilzai-1505', 'Babur had planned an expedition against Kandahar in 1506, which was governed by Shah Shuja better known as Shah Beg Arghun. Babur had marched towards Shniz where Wardak Afghans were residents. The site lay outside every kingdom mapped in the atlas that year.', 'Babur had planned an expedition against Kandahar in 1506, which was governed by Shah Shuja better known as Shah Beg Arghun. Babur had marched towards Shniz where Wardak Afghans were residents. The battle location is not recorded here.', 66.9069, 32.1061, true, ARRAY[]::text[]),
('battle-battle-of-chaul-1508', 'The Battle of Chaul was a naval battle between the Portuguese and an Egyptian Mamluk fleet in 1508 in the harbour of Chaul in India. The battle ended in a Mamluk victory. It followed the Siege of Cannanore in which a Portuguese garrison successfully resisted an attack by Southern Indian rulers. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Chaul was a naval battle between the Portuguese and an Egyptian Mamluk fleet in 1508 in the harbour of Chaul in India. The battle ended in a Mamluk victory. It followed the Siege of Cannanore in which a Portuguese garrison successfully resisted an attack by Southern Indian rulers. The battle location is not recorded here.', 72.9272, 18.5461, true, ARRAY[]::text[]),
('battle-battle-of-dabul-1509', 'The Battle of Dabul was a retaliatory attack by the forces of the Viceroy of Portuguese India, Francisco de Almeida, upon the port city of Dabul in the Sultanate of Bijapur. It occurred on 29 December 1508, in retaliation for attacking the Portuguese armada en route to the Battle of Diu. The site lay within the borders of Bijapur Sultanate that year (per Cliopatria).', 'The Battle of Dabul was a retaliatory attack by the forces of the Viceroy of Portuguese India, Francisco de Almeida, upon the port city of Dabul in the Sultanate of Bijapur. It occurred on 29 December 1508, in retaliation for attacking the Portuguese armada en route to the Battle of Diu. The battle location is not recorded here.', 73.1752, 17.5868, true, ARRAY['bijapur']::text[]),
('battle-battle-of-diu-1509', 'The Battle of Diu was a naval battle fought on 3 February 1509 in the Arabian Sea, in the port of Diu, India, between the Portuguese Empire and a joint fleet of the Sultan of Gujarat, the Mamlûk Burji Sultanate of Egypt and the Zamorin of Calicut. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Diu was a naval battle fought on 3 February 1509 in the Arabian Sea, in the port of Diu, India, between the Portuguese Empire and a joint fleet of the Sultan of Gujarat, the Mamlûk Burji Sultanate of Egypt and the Zamorin of Calicut. The recorded point lies outside the kingdoms mapped in the atlas that year.', 71, 20, false, ARRAY[]::text[]),
('battle-battle-of-ab-darrah-pass-1511', 'Battle of Ab Darrah Pass, or Battle of Pul-i Sangin, was the battle that took place in 1511, in the place called Ab Darrah between Uzbeks and Babur of Timurids. The site lay outside every kingdom mapped in the atlas that year.', 'Battle of Ab Darrah Pass, or Battle of Pul-i Sangin, was the battle that took place in 1511, in the place called Ab Darrah between Uzbeks and Babur of Timurids. The battle location is not recorded here.', 69.4667, 35.2667, true, ARRAY[]::text[]),
('battle-bengali-conquest-of-chittagong-1512', 'The Bengal–Mrauk U War was a conflict in the 16th century between the Bengal Sultanate and the Kingdom of Mrauk U. The site lay outside every kingdom mapped in the atlas that year.', 'The Bengal–Mrauk U War was a conflict in the 16th century between the Bengal Sultanate and the Kingdom of Mrauk U. The battle location is not recorded here.', 91.5, 22.9167, true, ARRAY[]::text[]),
('battle-battle-of-fatehpur-1519', 'The Second Battle of Thatta was fought near Thatta on 21st of December 1520, between the Samma Sultanate and the invading army of the Arghuns. The site lay within the borders of Samma (Sindh) that year (per Cliopatria).', 'The Second Battle of Thatta was fought near Thatta on 21st of December 1520, between the Samma Sultanate and the invading army of the Arghuns. The recorded point lies within the borders of Samma (Sindh) that year (per Cliopatria).', 67.9244, 24.7461, false, ARRAY['samma']::text[]),
('battle-battle-of-raichur-1520', 'The Battle of Raichur was fought between the Vijayanagara Empire and the Sultanate of Bijapur in 1520 in the town of Raichur, India. It resulted in a decisive victory for Vijayanagara forces, and the Bijapur ruler was defeated and pushed across the river Krishna. The site lay within the borders of Vijayanagara that year (per Cliopatria).', 'The Battle of Raichur was fought between the Vijayanagara Empire and the Sultanate of Bijapur in 1520 in the town of Raichur, India. It resulted in a decisive victory for Vijayanagara forces, and the Bijapur ruler was defeated and pushed across the river Krishna. The battle location is not recorded here.', 77.3506, 16.2, true, ARRAY['vijayanagara']::text[]),
('battle-battle-of-panipat-1526', 'The First Battle of Panipat, on 21 April 1526 was fought between the invading forces of Babur against Ibrahim Khan Lodi, the Sultan of Delhi, in North India. Babur''s forces, employing gunpowder firearms and cannons, defeated Ibrahim. The site lay outside every kingdom mapped in the atlas that year.', 'The First Battle of Panipat, on 21 April 1526 was fought between the invading forces of Babur against Ibrahim Khan Lodi, the Sultan of Delhi, in North India. Babur''s forces, employing gunpowder firearms and cannons, defeated Ibrahim. The recorded point lies outside the kingdoms mapped in the atlas that year.', 76.9728, 29.4017, false, ARRAY[]::text[]),
('battle-battle-of-khanwa-1527', 'The Battle of Khanwa was fought at Khanwa in modern-day Rajasthan on 16 March 1527, between the Mughal Empire, led by Babur, and the Kingdom of Mewar, led by Rana Sanga for supremacy of Northern India. The battle ended in a Mughal victory and was a major event in medieval Indian history. The site lay within the borders of Delhi Sultanate that year (per Cliopatria).', 'The Battle of Khanwa was fought at Khanwa in modern-day Rajasthan on 16 March 1527, between the Mughal Empire, led by Babur, and the Kingdom of Mewar, led by Rana Sanga for supremacy of Northern India. The battle ended in a Mughal victory and was a major event in medieval Indian history. The recorded point lies within the borders of Delhi Sultanate that year (per Cliopatria).', 77.5431, 27.0353, false, ARRAY['delhi-sultanate']::text[]),
('battle-battle-of-chanderi-1528', 'The Battle of Chanderi or  Siege of Chanderi took place in the aftermath of the Battle of Khanwa in which the Mughal Emperor Babur had defeated the Rajput Confederacy and firmly establish Mughal rule while crushing regrowing Rajput powers as the battle was fought for supremacy of Northern India between Rajputs and Mughals. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Chanderi or  Siege of Chanderi took place in the aftermath of the Battle of Khanwa in which the Mughal Emperor Babur had defeated the Rajput Confederacy and firmly establish Mughal rule while crushing regrowing Rajput powers as the battle was fought for supremacy of Northern India between Rajputs and Mughals. The recorded point lies outside the kingdoms mapped in the atlas that year.', 78.1, 24.7, false, ARRAY[]::text[]),
('battle-battle-of-ghaghra-1529', 'The Battle of Ghaghra, fought in 1529, was a major battle for the conquest of India by the Mughal Empire. It followed the first Battle of Panipat in 1526 and the Battle of Khanwa in 1527. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Ghaghra, fought in 1529, was a major battle for the conquest of India by the Mughal Empire. It followed the first Battle of Panipat in 1526 and the Battle of Khanwa in 1527. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 84.8, 25.8, false, ARRAY['mughal']::text[]),
('battle-battle-of-chausa-1539', 'The Battle of Chausa was a notable military engagement between the Mughal Emperor, Humayun, and the Afghan ruler, Sher Shah Suri. It was fought on 26 June 1539 at Chausa, 10 miles southwest of Buxar in modern-day Bihar, India. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Chausa was a notable military engagement between the Mughal Emperor, Humayun, and the Afghan ruler, Sher Shah Suri. It was fought on 26 June 1539 at Chausa, 10 miles southwest of Buxar in modern-day Bihar, India. The battle location is not recorded here.', 83.8823, 25.5075, true, ARRAY['mughal']::text[]),
('battle-battle-of-sammel-1544', 'The Battle of Sammel, also known as the Battle of Giri-Sumel, took place in 1544. It was fought near the villages of Giri and Sumel, between the Sur Empire under Sher Shah Suri and the Rathore army led by the commanders Jaita and Kumpa of Rao Maldeo Rathore. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Sammel, also known as the Battle of Giri-Sumel, took place in 1544. It was fought near the villages of Giri and Sumel, between the Sur Empire under Sher Shah Suri and the Rathore army led by the commanders Jaita and Kumpa of Rao Maldeo Rathore. The battle location is not recorded here.', 73.94, 26.2, true, ARRAY[]::text[]),
('battle-battle-of-vedalai-1549', 'The Battle of Vedalai took place in 1549 when Joao Fernandes Correa, the Portuguese captain at Vedalai, imposed tolls on Hindu pilgrims traveling to Rameswaram. This angered the Brahmins who sought assistance from Madurai leading to a Badaga invasion. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Vedalai took place in 1549 when Joao Fernandes Correa, the Portuguese captain at Vedalai, imposed tolls on Hindu pilgrims traveling to Rameswaram. This angered the Brahmins who sought assistance from Madurai leading to a Badaga invasion. The battle location is not recorded here.', 79.1, 9.275, true, ARRAY[]::text[]),
('battle-battle-of-punnaikayal-1553', 'The Battle of Punnaikayal was a conflict between the Portuguese and a combined force of Ottomans, Kingdom of Calicut and Vijayanagara troops. Seeking to end Portuguese dominance over the Coromandel Coast and its pearl fisheries, Vitthala of Vijayanagar allied with the Ottoman-Calicut Muslim fleet under Irapali. The site lay within the borders of Madurai Nayaks that year (per Cliopatria).', 'The Battle of Punnaikayal was a conflict between the Portuguese and a combined force of Ottomans, Kingdom of Calicut and Vijayanagara troops. Seeking to end Portuguese dominance over the Coromandel Coast and its pearl fisheries, Vitthala of Vijayanagar allied with the Ottoman-Calicut Muslim fleet under Irapali. The battle location is not recorded here.', 78.1119, 8.6322, true, ARRAY['madurai-nayaks']::text[]),
('battle-battle-at-machhiwara-1555', 'The Battle of Machhiwarra was fought between Mughal Empire and Suri Empire in 1555. The site lay within the borders of Sur Empire that year (per Cliopatria).', 'The Battle of Machhiwarra was fought between Mughal Empire and Suri Empire in 1555. The recorded point lies within the borders of Sur Empire that year (per Cliopatria).', 76.2, 30.91, false, ARRAY['sur']::text[]),
('battle-battle-of-sirhind-1555', 'The Battle of Sirhind was fought between the Mughal Empire and the Sur Empire in 1555. The site lay within the borders of Sur Empire that year (per Cliopatria).', 'The Battle of Sirhind was fought between the Mughal Empire and the Sur Empire in 1555. The battle location is not recorded here.', 76.386, 30.6251, true, ARRAY['sur']::text[]),
('battle-battle-of-panipat-1556', 'The Second Battle of Panipat was fought on 5 November 1556, between the Mughals under Akbar and king Hemu, titularly known as Hemchandra Vikramaditya. Hemchandra had conquered Delhi and Agra a few weeks earlier by defeating Mughal forces under Tardi Beg Khan in the Battle of Delhi. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Second Battle of Panipat was fought on 5 November 1556, between the Mughals under Akbar and king Hemu, titularly known as Hemchandra Vikramaditya. Hemchandra had conquered Delhi and Agra a few weeks earlier by defeating Mughal forces under Tardi Beg Khan in the Battle of Delhi. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 76.97, 29.39, false, ARRAY['mughal']::text[]),
('battle-battle-of-tughlaqabad-1556', 'The Battle of Tughlaqabad was a notable battle fought on 7 October 1556 between a Hindu general of the Sur known as Hemu and the forces of the Mughal Emperor Akbar led by Tardi Beg Khan at Tughlaqabad near Delhi. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Tughlaqabad was a notable battle fought on 7 October 1556 between a Hindu general of the Sur known as Hemu and the forces of the Mughal Emperor Akbar led by Tardi Beg Khan at Tughlaqabad near Delhi. The battle location is not recorded here.', 77.26, 28.5146, true, ARRAY['mughal']::text[]),
('battle-battle-of-mulleriyawa-1559', 'The Battle of Mulleriyawa in 1559 was part of the Sinhalese–Portuguese War. It was one of the most decisive battles in Sri Lankan history and considered as the worst defeat of the Portuguese during that period. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Mulleriyawa in 1559 was part of the Sinhalese–Portuguese War. It was one of the most decisive battles in Sri Lankan history and considered as the worst defeat of the Portuguese during that period. The recorded point lies outside the kingdoms mapped in the atlas that year.', 79.9482, 6.9363, false, ARRAY[]::text[]),
('battle-battle-of-talikota-1565', 'The Battle of Talikota, also known as that of Rakshasi-Tangadi, was a watershed battle fought between the Vijayanagara Empire and an alliance of the Deccan sultanates. The battle resulted in the defeat of Aliya Rama Raya which led to the eventual collapse of the polity and reconfigured Deccan politics. The site lay within the borders of Bijapur Sultanate that year (per Cliopatria).', 'The Battle of Talikota, also known as that of Rakshasi-Tangadi, was a watershed battle fought between the Vijayanagara Empire and an alliance of the Deccan sultanates. The battle resulted in the defeat of Aliya Rama Raya which led to the eventual collapse of the polity and reconfigured Deccan politics. The recorded point lies within the borders of Bijapur Sultanate that year (per Cliopatria).', 76.3118, 16.4733, false, ARRAY['bijapur']::text[]),
('battle-battle-of-thanesar-1567', 'Battle of Thanesar was fought on the eve of Solar eclipse holy bath fair on 9 April 1567, near Thanesar on the banks of the Saraswati Ghaggar River in the state of Haryana. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'Battle of Thanesar was fought on the eve of Solar eclipse holy bath fair on 9 April 1567, near Thanesar on the banks of the Saraswati Ghaggar River in the state of Haryana. The battle location is not recorded here.', 76.8249, 29.9688, true, ARRAY['mughal']::text[]),
('battle-siege-of-chittorgarh-1567', 'The siege of Chittorgarh was the military expedition of the Mughal Empire under Akbar against the Kingdom of Mewar that commenced in 1567 during which the Mughals successfully captured the fort of Chittorgarh after a hard-pressed siege which lasted for several months. The site lay outside every kingdom mapped in the atlas that year.', 'The siege of Chittorgarh was the military expedition of the Mughal Empire under Akbar against the Kingdom of Mewar that commenced in 1567 during which the Mughals successfully captured the fort of Chittorgarh after a hard-pressed siege which lasted for several months. The recorded point lies outside the kingdoms mapped in the atlas that year.', 74.647, 24.8863, false, ARRAY[]::text[]),
('battle-battle-of-tukaroi-1575', 'The Battle of Tukaroi, also known as the Battle of Bajhaura or the Battle of Mughulmari, was fought between the Mughal Empire and the Bengal Sultanate on 3 March 1575 near the village of Tukaroi in present-day Balasore District of Odisha. It resulted in a Mughal victory and greatly weakened the Bengal Sultanate. The site lay within the borders of Sur Empire that year (per Cliopatria).', 'The Battle of Tukaroi, also known as the Battle of Bajhaura or the Battle of Mughulmari, was fought between the Mughal Empire and the Bengal Sultanate on 3 March 1575 near the village of Tukaroi in present-day Balasore District of Odisha. It resulted in a Mughal victory and greatly weakened the Bengal Sultanate. The recorded point lies within the borders of Sur Empire that year (per Cliopatria).', 87.284, 21.973, false, ARRAY['sur']::text[]),
('battle-battle-of-raj-mahal-1576', 'The Battle of Rajmahal took place between the Mughal Empire and the Karrani Dynasty that ruled the Sultanate of Bengal in the 16th century. The battle resulted in a decisive victory for the Mughals. During the battle, the last Sultan of Bengal, Daud Khan Karrani, was captured and later executed by the Mughals. The site lay within the borders of Sur Empire that year (per Cliopatria).', 'The Battle of Rajmahal took place between the Mughal Empire and the Karrani Dynasty that ruled the Sultanate of Bengal in the 16th century. The battle resulted in a decisive victory for the Mughals. During the battle, the last Sultan of Bengal, Daud Khan Karrani, was captured and later executed by the Mughals. The battle location is not recorded here.', 87.84, 25.05, true, ARRAY['sur']::text[]),
('battle-battle-of-haldighati-1576', 'The battle of Haldighati was fought on 18 June 1576 between the Mewar forces led by Maharana Pratap, and the Mughal forces led by Man Singh I of Amber. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The battle of Haldighati was fought on 18 June 1576 between the Mewar forces led by Maharana Pratap, and the Mughal forces led by Man Singh I of Amber. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 73.6978, 24.8922, false, ARRAY['mughal']::text[]),
('battle-battle-of-ahobilam-1579', 'The Battle of Ahobilam was a military conflict fought between the Vijayanagara Empire and the Golconda Sultanate in the year 1579 A.D. Yatindra Mahadesikan the seventh Jiyar of the Ahobilam Mutt, accompanied the Vijayanagara commanders Kondaraju Venkataraju and Kondaraju Tirumala Raju and guided them in the expedition. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Ahobilam was a military conflict fought between the Vijayanagara Empire and the Golconda Sultanate in the year 1579 A.D. Yatindra Mahadesikan the seventh Jiyar of the Ahobilam Mutt, accompanied the Vijayanagara commanders Kondaraju Venkataraju and Kondaraju Tirumala Raju and guided them in the expedition. The recorded point lies outside the kingdoms mapped in the atlas that year.', 78.7167, 15.1333, false, ARRAY[]::text[]),
('battle-battle-of-bhuchar-mori-1591', 'The Battle of Bhuchar Mori, also known as Battle of Dhrol, was fought between the army of Kathiawar led by Nawanagar State and the Mughal army at Bhuchar Mori plateau near Dhrol, Saurashtra. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Bhuchar Mori, also known as Battle of Dhrol, was fought between the army of Kathiawar led by Nawanagar State and the Mughal army at Bhuchar Mori plateau near Dhrol, Saurashtra. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 70.4, 22.582, false, ARRAY['mughal']::text[]),
('battle-battle-of-herat-1598', 'Battle of Herat took place on August 9, 1598, between the Shaybanid Khanate and the Safavid Empire for Khorasan and Balkh. The battle resulted in the complete defeat of the Uzbeks and Safavid Empire fully restored its power in Khorasan and got back the region. The site lay outside every kingdom mapped in the atlas that year.', 'Battle of Herat took place on August 9, 1598, between the Shaybanid Khanate and the Safavid Empire for Khorasan and Balkh. The battle resulted in the complete defeat of the Uzbeks and Safavid Empire fully restored its power in Khorasan and got back the region. The battle location is not recorded here.', 62.2031, 34.3419, true, ARRAY[]::text[]),
('battle-ghazni-skirmish-1601', 'The clash at Ghazni was a brief engagement, fought between the Roshanis led by Jalala Ansari, better known as Jalala Tariki, the son of former Roshanid leader Pir Roshan, and Hazaras of Ghazni in 1601, following a conflict involving the Lohani Afghans at Ghazni. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The clash at Ghazni was a brief engagement, fought between the Roshanis led by Jalala Ansari, better known as Jalala Tariki, the son of former Roshanid leader Pir Roshan, and Hazaras of Ghazni in 1601, following a conflict involving the Lohani Afghans at Ghazni. The battle location is not recorded here.', 68.4233, 33.5492, true, ARRAY['mughal']::text[]),
('battle-battle-of-balkh-1602', 'The site lay outside every kingdom mapped in the atlas that year.', 'The battle location is not recorded here.', 66.8989, 36.7581, true, ARRAY[]::text[]),
('battle-battle-of-vannarapannai-1619', 'The Battle of Vannarpannai was a battle fought in 1619 between the forces of Cankili II, the last ruler of the Jaffna Kingdom, and the Portuguese under Phillippe de Oliveira. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Vannarpannai was a battle fought in 1619 between the forces of Cankili II, the last ruler of the Jaffna Kingdom, and the Portuguese under Phillippe de Oliveira. The battle location is not recorded here.', 80.0167, 9.6833, true, ARRAY[]::text[]),
('battle-battle-of-rohilla-1621', 'The Battle of Rohilla, also known as the Battle of Hargobindpur, was a 1621 campaign by the Mughal Empire against the growing influence of the Sikhs. The battle was fought on 4 October 1621. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Rohilla, also known as the Battle of Hargobindpur, was a 1621 campaign by the Mughal Empire against the growing influence of the Sikhs. The battle was fought on 4 October 1621. The battle location is not recorded here.', 75.4797, 31.6894, true, ARRAY['mughal']::text[]),
('battle-battle-of-amritsar-1634', 'The Battle of Amritsar was fought during Mukhlis Khan''s campaign against Guru Hargobind and the Sikhs on 14 April 1634. The battle took place over two days and was a result of increasing tensions between the Mughal government and Guru Hargobind. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Amritsar was fought during Mukhlis Khan''s campaign against Guru Hargobind and the Sikhs on 14 April 1634. The battle took place over two days and was a result of increasing tensions between the Mughal government and Guru Hargobind. The battle location is not recorded here.', 74.877, 31.6269, true, ARRAY['mughal']::text[]),
('battle-battle-of-lahira-1634', 'The Battle of Lahira, also known as the Battle of Gurusar or the Battle of Mehraj, was fought between the Mughal Empire and Sikhs assisted by the Kangra State in 1631 or 1634. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Lahira, also known as the Battle of Gurusar or the Battle of Mehraj, was fought between the Mughal Empire and Sikhs assisted by the Kangra State in 1631 or 1634. The battle location is not recorded here.', 74.9519, 30.2133, true, ARRAY['mughal']::text[]),
('battle-battle-of-five-lamas-1634', 'The Second Tibetan Invasion of Bhutan or the Second Battle of Simtokha Dzong was a military confrontation in 1634 between the supporters of Zhabdrung Ngawang Namgyal and the forces of the Tibetan Tsangpa dynasty and several Bhutanese lamas allied against him. The site lay outside every kingdom mapped in the atlas that year.', 'The Second Tibetan Invasion of Bhutan or the Second Battle of Simtokha Dzong was a military confrontation in 1634 between the supporters of Zhabdrung Ngawang Namgyal and the forces of the Tibetan Tsangpa dynasty and several Bhutanese lamas allied against him. The battle location is not recorded here.', 89.6694, 27.4381, true, ARRAY[]::text[]),
('battle-battle-of-kartarpur-1635', 'The Battle of Kartarpur occurred on 25 April 1635. It was the final major military engagement of Guru Hargobind, the sixth Sikh Guru, against the imperial forces of the Mughal Empire. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Kartarpur occurred on 25 April 1635. It was the final major military engagement of Guru Hargobind, the sixth Sikh Guru, against the imperial forces of the Mughal Empire. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 75.5792, 31.3256, false, ARRAY['mughal']::text[]),
('battle-battle-of-gannoruwa-1638', 'The Battle of Gannoruwa was a battle of the Sinhalese–Portuguese War fought in 1638 between the occupying Portuguese forces and the Sinhalese King''s army at Gannoruwa in the District of Kandy, Sri Lanka. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Gannoruwa was a battle of the Sinhalese–Portuguese War fought in 1638 between the occupying Portuguese forces and the Sinhalese King''s army at Gannoruwa in the District of Kandy, Sri Lanka. The recorded point lies outside the kingdoms mapped in the atlas that year.', 80.6018, 7.2795, false, ARRAY[]::text[]),
('battle-battle-of-kiratpur-1638', 'The Battle of Kiratpur, also known as the Battle of Kiratpur Sahib, took place between the Sikhs, commanded by Guru Hargobind, and the Mughals, commanded by the Ruler and Pathans of Ropar. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Kiratpur, also known as the Battle of Kiratpur Sahib, took place between the Sikhs, commanded by Guru Hargobind, and the Mughals, commanded by the Ruler and Pathans of Ropar. The battle location is not recorded here.', 76.5635, 31.1821, true, ARRAY['mughal']::text[]),
('battle-action-of-30-september-1639-1639', 'Action of 30 September 1639, 1639. Wikidata records its date and place; there is no article that describes this battle on its own. The site lay outside every kingdom mapped in the atlas that year.', 'Action of 30 September 1639, 1639. Wikidata records its date; there is no article that describes this battle on its own. The battle location is not recorded here.', 73.8, 15.402, true, ARRAY[]::text[]),
('battle-skirmish-at-pipli-1640', 'Mirza Mumin''s assault and subsequent destruction of the Danish factory at Pipli in Bengal by Mughal forces occurred in late 1641. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'Mirza Mumin''s assault and subsequent destruction of the Danish factory at Pipli in Bengal by Mughal forces occurred in late 1641. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 87.3364, 21.5642, false, ARRAY['mughal']::text[]),
('battle-capture-of-the-ship-the-bengali-prize-1642', 'The capture of Den Bengalske Prise by two Danish yachts took place in late 1642 in the Bay of Bengal. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The capture of Den Bengalske Prise by two Danish yachts took place in late 1642 in the Bay of Bengal. The battle location is not recorded here.', 85.8333, 20.1167, true, ARRAY['mughal']::text[]),
('battle-skirmish-of-narsapur-road-1643', 'The skirmish of Narsapur Road took place on 14 December 1643 at the road off Narsapur in Golconda between two Danish ships and one Bengali ship. The site lay within the borders of Golconda Sultanate that year (per Cliopatria).', 'The skirmish of Narsapur Road took place on 14 December 1643 at the road off Narsapur in Golconda between two Danish ships and one Bengali ship. The battle location is not recorded here.', 81.6833, 16.4333, true, ARRAY['golconda']::text[]),
('battle-capture-of-st-michael-1644', 'The Capture of St. Michael or the Seizure of St. Michael, was a Danish seizure of a Bengali ship in the Bay of Bengal. The Danes captured the Bengali ship and the vessel was subsequently incorporated into the Danish Navy given the name St. Michael. The site lay outside every kingdom mapped in the atlas that year.', 'The Capture of St. Michael or the Seizure of St. Michael, was a Danish seizure of a Bengali ship in the Bay of Bengal. The Danes captured the Bengali ship and the vessel was subsequently incorporated into the Danish Navy given the name St. Michael. The battle location is not recorded here.', 88, 15, true, ARRAY[]::text[]),
('battle-action-off-pipli-river-1644', 'The action off Pipli River took place on 21 January 1644 at the mouth of the Pipli River in Bengal between a Danish yacht and a Bengali ship. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The action off Pipli River took place on 21 January 1644 at the mouth of the Pipli River in Bengal between a Danish yacht and a Bengali ship. The recorded point lies within the borders of Mughal Empire that year (per Cliopatria).', 87.3919, 21.555, false, ARRAY['mughal']::text[]),
('battle-capture-of-den-lille-elefant-1644', 'The capture of Den Lille Elefant by a Danish frigate took place in February 1644 in the Bay of Bengal. The site lay outside every kingdom mapped in the atlas that year.', 'The capture of Den Lille Elefant by a Danish frigate took place in February 1644 in the Bay of Bengal. The battle location is not recorded here.', 88, 15, true, ARRAY[]::text[]),
('battle-battle-of-pulicat-1644', 'The Battle of Pulicat was a military conflict fought between the forces of the Vijayanagara Empire and the Golconda Sultanate near Pulicat on the Coromandel Coast. After advancing southward and threatening the Dutch settlement at Pulicat the Golconda army was met by a large force sent by the Sriranga III. The site lay outside every kingdom mapped in the atlas that year.', 'The Battle of Pulicat was a military conflict fought between the forces of the Vijayanagara Empire and the Golconda Sultanate near Pulicat on the Coromandel Coast. After advancing southward and threatening the Dutch settlement at Pulicat the Golconda army was met by a large force sent by the Sriranga III. The recorded point lies outside the kingdoms mapped in the atlas that year.', 80.3185, 13.4177, false, ARRAY[]::text[]),
('battle-battle-of-balasore-1647', 'The Battle of Balasore was an engagement between Bengali and English ships against Danish ships at Balasore. When the English failed to persuade the Danes, the Bengalis started attacking the English vessel, yet the English were rescued by the Dutch. The site lay within the borders of Mughal Empire that year (per Cliopatria).', 'The Battle of Balasore was an engagement between Bengali and English ships against Danish ships at Balasore. When the English failed to persuade the Danes, the Bengalis started attacking the English vessel, yet the English were rescued by the Dutch. The battle location is not recorded here.', 86.925, 21.5033, true, ARRAY['mughal']::text[]),
